@test
def test_dt():
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-30", None, 5, "D").tolist()] == E_dr_d
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-03-09 22:00", None, 6, "h").tolist()] == E_dr_h
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-01", None, 4, "15min").tolist()] == E_dr_t
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-01 00:00:58", None, 4, "s").tolist()] == E_dr_s
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-01", None, 3, "250ms").tolist()] == E_dr_ms
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-04", "2024-01-12", None, "B").tolist()] == E_dr_b
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-03", None, 4, "W").tolist()] == E_dr_w
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-03", None, 3, "W-FRI").tolist()] == E_dr_wfri
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-31", None, 5, "ME").tolist()] == E_dr_me
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-15", None, 3, "ME").tolist()] == E_dr_me2
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-15", None, 3, "MS").tolist()] == E_dr_ms_
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-01", None, 4, "QE").tolist()] == E_dr_qe
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-02-01", None, 3, "QS").tolist()] == E_dr_qs
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-03-01", None, 3, "YE").tolist()] == E_dr_ye
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-03-01", None, 3, "YS").tolist()] == E_dr_ys
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-02-27", "2024-03-02", None, "D").tolist()] == E_dr_d_end
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range("2024-01-01", None, 4, "2D").tolist()] == E_dr_d2
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S.%f") for x in pd.date_range(None, "2024-01-10", 3, "D").tolist()] == E_dr_endp
    t = pd.Timestamp("2024-03-05 10:20:30.123456")
    assert [t.year, t.month, t.day, t.hour, t.minute, t.second, t.microsecond, t.day_of_week, t.dayofyear, t.quarter, 1 if t.is_leap_year else 0, t.days_in_month] == E_ts
    assert [t.day_name(), t.month_name(), str(t), t.isoformat(), t.strftime("%a %d %b %Y %H:%M:%S.%f %j"), str(t.normalize())] == E_tsn
    u = pd.Timedelta("1 days 02:03:04.5")
    assert [u.days, u.seconds, u.microseconds, u.total_seconds(), str(u), str(u + pd.Timedelta(None, 0, 30)), str(pd.Timestamp("2024-01-01") + u), str(pd.Timestamp("2024-03-01") - pd.Timestamp("2024-01-01"))] == E_td
    assert close(vals(sd.dt.year), E_dt_year)
    assert close(vals(sd.dt.month), E_dt_month)
    assert close(vals(sd.dt.day), E_dt_day)
    assert close(vals(sd.dt.hour), E_dt_hour)
    assert close(vals(sd.dt.minute), E_dt_minute)
    assert close(vals(sd.dt.dayofweek), E_dt_dayofweek)
    assert close(vals(sd.dt.dayofyear), E_dt_dayofyear)
    assert close(vals(sd.dt.quarter), E_dt_quarter)
    assert close(vals(sd.dt.days_in_month), E_dt_days_in_month)
    assert ds(sd.dt.day_name()) == E_dt_dn
    assert ds(sd.dt.month_name()) == E_dt_mn
    assert ds(sd.dt.strftime("%Y/%m/%d %H%M")) == E_dt_sf
    assert ds(sd.dt.normalize()) == E_dt_norm
    assert ds(sd.dt.is_month_end) == E_dt_ime
    assert close(vals((sd - pd.Timestamp("2023-12-25")).dt.days), E_td_days)
    assert close(vals((sd - pd.Timestamp("2023-12-25")).dt.total_seconds()), E_td_tsec)
    assert ds(sd + pd.Timedelta(None, 0, 7)) == E_dt_plus
    assert ds(pd.to_datetime(pd.Series(["2024-02-29", "2023-07-04", None]))) == E_to_dt
    assert ds(sd > pd.Timestamp("2023-12-31")) == E_dt_cmp
