    assert close(fvals((sr.resample("ME").mean()).to_frame()) , E_rME_mean_v)
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S") for x in (sr.resample("D").min()).index.tolist()] == E_rD_min_i
    assert close(fvals((sr.resample("D").min()).to_frame()) , E_rD_min_v)
