    assert close(fvals((sr.resample("D").count()).to_frame()) , E_rD_count_v)
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S") for x in (sr.resample("D").first()).index.tolist()] == E_rD_first_i
    assert close(fvals((sr.resample("D").first()).to_frame()) , E_rD_first_v)
    assert [pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S") for x in (sr.resample("D").last()).index.tolist()] == E_rD_last_i
    assert close(fvals((sr.resample("D").last()).to_frame()) , E_rD_last_v)
    oh = sr.resample("2D").ohlc()
    assert close(fvals(oh), E_oh)
    assert [pd.Timestamp(x).strftime("%Y-%m-%d") for x in oh.index.tolist()] == E_oh_i
    assert close(fvals(pd.merge_asof(tr, qt, "time")[["q", "bid"]]), E_asof_b)
    assert close(fvals(pd.merge_asof(tr, qt, "time", None, "forward")[["q", "bid"]]), E_asof_f)
    assert close(fvals(pd.merge_asof(tr, qt, "time", None, "nearest")[["q", "bid"]]), E_asof_n)
    assert close(fvals(pd.merge_asof(tr, qt, "time", None, "backward", pd.Timedelta(None, 0, 0, 0, 0, 10))[["q", "bid"]]), E_asof_tol)
    assert close(fvals(pd.merge_asof(tr, qt, "time", None, "backward", None, ("_x", "_y"), False)[["q", "bid"]]), E_asof_nx)
